import type { FoodGroup, FoodMeasure, Macros, MealType } from './types'
import { turkishLower } from './turkish'

/**
 * Besin kategorisi. İlk dokuzu servis bağlamını anlatır (ana yemek, çorba, garnitür).
 *
 * `temel_gida` ham market ve pazar malzemeleri içindir: çiğ kıyma, kuru nohut,
 * zeytinyağı, taze sebze. Bunlar servis bağlamı taşımaz, zorlama eşlemeler kategori
 * ile besin grubu tutarlılığını da bozuyordu. Backend food_category enum'unun
 * aynası, migration 000025 ile eklendi.
 */
export type FoodCategory =
  | 'kahvaltilik'
  | 'corba'
  | 'ana_yemek'
  | 'yan'
  | 'salata_yogurt'
  | 'meyve_kuruyemis'
  | 'atistirmalik'
  | 'tatli'
  | 'icecek'
  | 'temel_gida'

export const FOOD_CATEGORIES: { key: FoodCategory; label: string }[] = [
  { key: 'kahvaltilik', label: 'Kahvaltılık' },
  { key: 'corba', label: 'Çorbalar' },
  { key: 'ana_yemek', label: 'Ana Yemekler' },
  { key: 'yan', label: 'Pilav & Garnitür' },
  { key: 'salata_yogurt', label: 'Salata & Yoğurt' },
  { key: 'meyve_kuruyemis', label: 'Meyve & Kuruyemiş' },
  { key: 'atistirmalik', label: 'Atıştırmalık & Fast Food' },
  { key: 'tatli', label: 'Tatlılar' },
  { key: 'icecek', label: 'İçecekler' },
  { key: 'temel_gida', label: 'Temel Gıdalar' },
]

export function categoryMeta(key: FoodCategory) {
  return FOOD_CATEGORIES.find((c) => c.key === key)!
}

/** Diyet uyumu etiketleri; filtreleme ve aile içi kişiselleştirme için */
export type DietTag = 'vejetaryen' | 'vegan' | 'glutensiz' | 'laktozsuz'

export const DIET_TAGS: { key: DietTag; label: string }[] = [
  { key: 'vejetaryen', label: 'Vejetaryen' },
  { key: 'vegan', label: 'Vegan' },
  { key: 'glutensiz', label: 'Glutensiz' },
  { key: 'laktozsuz', label: 'Laktozsuz' },
]

export interface SeedFood {
  name: string
  groups: FoodGroup[]
  category: FoodCategory
  /** Bu besin için doğal miktar ölçüsü; miktar girişi buna göre sorulur */
  measure: FoodMeasure
  /** 1 ölçü için yaklaşık makrolar; hassas takip değil, denge pusulası */
  macros: Macros
  /** Besin hakkında kısa, basit bilgi (rehber popup'ında gösterilir) */
  description: string
  // --- Zenginleştirme metrikleri (öncelikli) ---
  /** 1 ölçünün yaklaşık ağırlığı (g); makro ölçekleme ve porsiyon referansı */
  gramPerMeasure: number
  /** 1 ölçü için yaklaşık lif (g); kaloriden çok tokluk/denge sinyali */
  fiberG: number
  /** Bu besnin doğal olarak yakıştığı öğünler; öneri ve sıralamada kullanılır */
  suitableMeals: MealType[]
  /** Diyet uyumu etiketleri (vegan ⊂ vejetaryen; ikisi de eklenir) */
  dietTags: DietTag[]
  // --- Zenginleştirme metrikleri (ikincil) ---
  /** Sevimli görsel ipucu (kart ve kayıt akışında) */
  emoji: string
  /** Kayıtta önerilen varsayılan miktar; tek dokunuşluk kayıt için */
  defaultQuantity: number
  /** Arama eşanlamlıları; autocomplete eşleşmesini genişletir */
  aliases: string[]
  /** Sıvı katkısı (ml); su takibine sayılabilir; katı besinlerde tanımsız */
  liquidMl?: number
  /** Daha dengeli/hafif alternatif besnin adı; "denge hamlesi" önerisi */
  lighterAlternative?: string
}

